          <main className="flex-1 overflow-auto p-6">
            <div className="max-w-7xl mx-auto">
              <AuthenticatedRoutes />
            </div>
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <MainApp />
        <Toaster />
      </TooltipProvider>
    </QueryClientProvider>
  );
}

export default App;

